def apply(inputs, premises):
    covered_domestic_service = inputs["service_kind"] == premises["domestic_service_term"] and inputs["service_setting"] in premises["covered_settings"]
    exclusion_applies = covered_domestic_service and inputs["qualifying_remuneration"] < premises["remuneration_threshold"]
    answer = "Entailment" if exclusion_applies else "Contradiction"
    return {"answer": answer}

